generata:
GET COLLECTION percorsi_raccolta;
GROUP PARTITION TRUE BY .livello_priorita INTO .percorsiPerLivello
FILTER CASE WHERE .turno_notturno = TRUE

GET COLLECTION strumentazioni;
FILTER CASE WHERE .nome_dispositivo IN ( 'strumentazione1', 'strumentazione2' ) AND .ubicazione != 'deposito B';
GROUP PARTITION TRUE BY .nome_dispositivo INTO .risultato;

GET COLLECTION equipments;
FILTER CASE WHERE NOT (.storage_location = 'deposito B') AND .device_name IN ( 'Microscopio', 'Telescopio' );
GROUP PARTITION TRUE BY .device_name INTO .ordersByDevice

GET COLLECTION experiments; 
JOIN OF COLLECTIONS experiments AS a, equipments AS b CASE WHERE .a._id = .b._id; 
FILTER CASE WHERE .a.duration_hours > 0 AND .b.voltage > 0;

GET COLLECTION arnia;
JOIN OF COLLECTIONS arnia AS a, macchinari AS b CASE WHERE a._id = b.id_macchinari;
SAVE AS arniaMacchinari@ft_it_077

GET COLLECTION lawyers;
JOIN OF COLLECTIONS lawyers AS a, cases AS b CASE WHERE .a._id = .b.dossier_id;
GET COLLECTION cases;

GET COLLECTION voyages; 
FILTER CASE WHERE .is_delayed = TRUE AND .departure = 'Genova'; 
JOIN OF COLLECTIONS voyages AS a, missions AS b CASE WHERE .a._id = .b.voyage_id; 
FILTER CASE WHERE .a.route_points IN_RANGE [0, 1000];

GET COLLECTION cases; 
FILTER CASE WHERE .dossier_id != 'F-2023-02' OR .year IN_RANGE [2011, 2023]; 
JOIN OF COLLECTIONS cases AS a, lawyers AS b CASE WHERE .a._id = .b.worker_id; 
FILTER CASE WHERE .a.fascicolo != .b.worker_id; 
MERGE COLLECTIONS a, b REMOVE DUPLICATES;
